CAClB,4BAAgC,CAChC,sCAA0C,CAC1C,eACF,CACA,qCACE,WAAY,CACZ,iBAAkB,CAClB,yDAA6D,CAC7D,0BACF,CACA,wDACE,yDAA6D,CAC7D,wCAA4C,CAC5C,2DACF,CACA,mCACE,QAAW,oBAAuB,CAClC,IAAM,uBAA0B,CAClC,CAEA,gCACE,YAAa,CACb,kBAAmB,CACnB,QAAS,CACT,cAAe,CACf,cAAe,CACf,aACF,CACA,2BACE,mBAAoB,CACpB,kBAAmB,CACnB,OAAQ,CACR,kBACF,CACA,0BACE,oBAAqB,CACrB,UAAW,CACX,UAAW,CACX,iBAAkB,CAClB,4BAAgC,CAChC,uCAA2C,CAC3C,eAAgB,CAChB,qBACF,CACA,4BACE,aAAc,CACd,WAAY,CACZ,iDAAoD,CACpD,iBAAkB,CAClB,0BACF,CAEA,+BACE,YAAa,CACb,cAAe,CACf,WAAY,CACZ,cACF,CACA,8BACE,aAAc,CACd,aAAc,CACd,iCAAqC,CACrC,uCAA2C,CAC3C,iBAAkB,CAClB,eAAgB,CAChB,oBACF,CAEA,4BACE,YAAa,CACb,kBAAmB,CACnB,OAAQ,CACR,cACF,CACA,4BACE,6CAAgD,CAChD,cAAe,CACf,eAAgB,CAChB,kBAAmB,CACnB,aAAc,CACd,kDAAqD,CACrD,wBAAyB,CACzB,iBAAkB,CAClB,gBAAiB,CACjB,cAAe,CACf,sDAAyD,CACzD,oCACF,CACA,iDACE,0BAA2B,CAC3B,4CACF,CACA,qCACE,qCAAsC,CACtC,kBACF,CACA,8BACE,cAAe,CACf,aAAc,CACd,eAAgB,CAChB,MACF,CACA,+BACE,cAAe,CACf,aAAc,CACd,eAAgB,CAChB,MACF,CAGA,gCACE,MAAO,CACP,eAAgB,CAChB,iBAAkB,CAClB,iBAAkB,CAClB,YAAa,CACb,qBAAsB,CACtB,QAAS,CACT,sBAAuB,CACvB,YACF,CAEA,6BACE,MAAO,CACP,YAAa,CACb,qBAAsB,CACtB,kBAAmB,CACnB,sBAAuB,CACvB,OAAQ,CACR,aACF,CACA,6BACE,cAAe,CACf,aAAc,CACd,WACF,CACA,6BACE,cAAe,CACf,QAAS,CACT,iBACF,CACA,6BACE,cAAe,CACf,QAAS,CACT,WACF,CAEA,8BACE,YACF,CACA,+BACE,wBACF,CACA,oCACE,0BACF,CAEA,iCACE,aAAc,CACd,gBAAiB,CACjB,kBAAmB,CACnB,gCAAoC,CACpC,oCAAwC,CACxC,qCAAsC,CACtC,qBAAsB,CACtB,wBAAyB,CACzB,YACF,CAEA,+CACE,gCAAoC,CACpC,gCACF,CAEA,gCACE,cAAe,CACf,eAAgB,CAChB,aAAc,CACd,iBAAkB,CAClB,wBAAyB,CACzB,oBACF,CAEA,kCACE,cAAe,CACf,eAAgB,CAChB,aAAc,CACd,oBAAqB,CACrB,qBACF,CAEA,mDACE,YACF,CAEA,+BACE,YAAa,CACb,OAAQ,CACR,cAAe,CACf,aAAc,CACd,aACF,CACA,sBACE,qDACF,CACA,mCAAoB,oBAAuB,CAC3C,mCAAoB,oBAAuB,CAC3C,6BACE,YAAgB,WAAc,CAC9B,IAAM,SAAY,CACpB,CAGA,kCACE,YAAa,CACb,OAAQ,CACR,gBAAiB,CACjB,wCAA4C,CAC5C,kEAAwE,CACxE,aACF,CAEA,6BACE,MAAO,CACP,gBAAiB,CACjB,oCAAwC,CACxC,iBAAkB,CAClB,gCAAoC,CACpC,aAAc,CACd,6CAAgD,CAChD,cAAe,CACf,WAAY,CACZ,YAAa,CACb,4BACF,CACA,mCACE,oBAAqB,CACrB,gCACF,CACA,0CACE,aAAc,CACd,iBACF,CAEA,2BACE,UAAW,CACX,WAAY,CACZ,oCAAwC,CACxC,iBAAkB,CAClB,kDAAqD,CACrD,UAAW,CACX,cAAe,CACf,cAAe,CACf,YAAa,CACb,kBAAmB,CACnB,aAAc,CACd,mBAAoB,CACpB,wCACF,CACA,gDACE,kDAAqD,CACrD,qBACF,CACA,oCACE,WAAY,CACZ,kBACF,CAGA,mDACE,SACF,CACA,yDACE,sBACF,CACA,yDACE,8BAAkC,CAClC,iBACF,CACA,+DACE,8BACF,CAGA,6BACE,oCAAwC,CACxC,gCAAoC,CACpC,aAAc,CACd,iBAAkB,CAClB,eAAgB,CAChB,cAAe,CACf,cAAe,CACf,aAAc,CACd,0BAA2B,CAC3B,aACF,CACA,kDACE,gCACF,CACA,sCACE,WAAY,CACZ,kBACF,CAGA,iCACE,iBACF,CAEA,kCACE,iBAAkB,CAClB,SAAU,CACV,SAAU,CACV,YAAa,CACb,OAAQ,CACR,iCAAqC,CACrC,qCAAyC,CACzC,iBAAkB,CAClB,eAAgB,CAChB,oCAAqC,CACrC,UAAW,CACX,SAAU,CACV,oDACF,CACA,kCACE,GAAK,SAAY,CACnB,CAEA,iCACE,WAAY,CACZ,sBAAuB,CACvB,aAAc,CACd,cAAe,CACf,aAAc,CACd,eAAgB,CAChB,cAAe,CACf,iBAAkB,CAClB,2BACF,CACA,uCACE,+BACF,CAGA,oCACE,YAAa,CACb,qBAAsB,CACtB,OACF,CAEA,qCACE,UAAW,CACX,eAAgB,CAChB,oCAAwC,CACxC,iBAAkB,CAClB,gCAAoC,CACpC,aAAc,CACd,6CAAgD,CAChD,cAAe,CACf,eAAgB,CAChB,YAAa,CACb,qBAAsB,CACtB,eACF,CACA,2CACE,oBACF,CAEA,uCACE,YAAa,CACb,OAAQ,CACR,wBACF,CAEA,kCACE,oCAAwC,CACxC,iBAAkB,CAClB,eAAgB,CAChB,cAAe,CACf,cAAe,CACf,6CAAgD,CAChD,2BACF,CACA,4BACE,8BAAkC,CAClC,aACF,CACA,kCACE,+BACF,CACA,8BACE,+BAAmC,CACnC,aACF,CACA,oCACE,8BACF,CAGA,yBACE,8BACE,eAAgB,CAChB,OACF,CACA,4BACE,cACF,CACA,gCACE,cACF,CACA,4BACE,aAAc,CACd,aACF,CACA,gCACE,eAAgB,CAChB,OACF,CACA,iCACE,aAAc,CACd,gBACF,CACA,kCACE,cACF,CACA,kCACE,SAAU,CACV,SAAU,CACV,eACF,CACA,iCACE,cAAe,CACf,eACF,CACA,qCACE,cACF,CACA,kCACE,eACF,CACA,6BACE,cAAe,CACf,eACF,CACA,2BACE,UAAW,CACX,WAAY,CACZ,cACF,CACF","sourcesContent":["<template>\r\n  <div class=\"hero-chat\">\r\n    <!-- 顶部：英灵信息栏 -->\r\n    <div class=\"chat-header\">\r\n      <button class=\"back-btn\" @click=\"store.goBack()\" title=\"返回列表\">←</button>\r\n      <div class=\"hero-info\">\r\n        <span class=\"hero-log-icon\">{{ store.selectedHero?.log }}</span>\r\n        <span class=\"hero-status-dot\" :class=\"onlineClass\"></span>\r\n        <span class=\"hero-name\">{{ store.selectedHero?.displayName }}</span>\r\n        <span v-if=\"currentMood\" class=\"hero-mood\">{{ currentMood }}</span>\r\n      </div>\r\n      <button class=\"recall-btn\" @click=\"onRecall\" title=\"撤回上一条\" :disabled=\"store.messages.length === 0\">↩</button>\r\n      <button v-if=\"!store.selectedHero?.isCompanion\" class=\"recall-btn anecdote-btn\" @click=\"store.openAnecdotes(store.selectedHero)\" title=\"回忆碎片\">📖</button>\r\n      <button class=\"clear-btn\" @click=\"store.clearChat()\" title=\"清空对话\">🗑</button>\r\n    </div>\r\n\r\n    <!-- 沉睡横幅 -->\r\n    <div v-if=\"sleeping\" class=\"sleep-banner\">💤 {{ store.selectedHero?.displayName }} 正沉睡于英灵殿深处，只有模糊的梦呓……</div>\r\n\r\n    <!-- 共鸣状态条（英灵共鸣系统 v2：残响/羁绊/执念/被动/英灵技） -->\r\n    <div v-if=\"!store.selectedHero?.isCompanion && !sleeping\" class=\"resonance-panel\">\r\n      <div class=\"resonance-head\">\r\n        <span class=\"resonance-title\">✦ 残响之力</span>\r\n        <span class=\"resonance-val\">{{ resonance }}<em>/100</em></span>\r\n        <span class=\"resonance-status\" :class=\"'status-' + spiritStatusClass\">{{ spiritStatusText }}</span>\r\n        <span v-if=\"cooldown > 0\" class=\"resonance-cooldown\">冷却 {{ cooldown }}</span>\r\n      </div>\r\n      <div class=\"resonance-bar-bg\">\r\n        <div\r\n          class=\"resonance-bar-fill\"\r\n          :class=\"{ 'resonance-bar-full': resonance >= 100 }\"\r\n          :style=\"{ width: Math.min(100, resonance) + '%' }\"\r\n        ></div>\r\n      </div>\r\n      <div class=\"resonance-sub\">\r\n        <span class=\"sub-item\">羁绊 {{ bond }}\r\n          <span class=\"sub-bar\"><i :style=\"{ width: Math.min(100, bond) + '%' }\"></i></span>\r\n        </span>\r\n        <span class=\"sub-item\" :title=\"obsessionDesc\">执念 {{ obsession }}%</span>\r\n        <span class=\"sub-item\" v-if=\"releasedCount > 0\">已释放 ×{{ releasedCount }}</span>\r\n      </div>\r\n      <div v-if=\"passiveNames.length\" class=\"passive-tags\">\r\n        <span v-for=\"p in passiveNames\" :key=\"p\" class=\"passive-tag\">{{ p }}</span>\r\n      </div>\r\n      <div class=\"skill-row\">\r\n        <button class=\"skill-btn\" :disabled=\"!canRelease\" :title=\"skillBtnTitle\" @click=\"onReleaseSkill\">\r\n          {{ skillName || '英灵技' }}\r\n        </button>\r\n        <span v-if=\"releaseMsg\" class=\"release-msg\">{{ releaseMsg }}</span>\r\n        <span v-else-if=\"!canRelease\" class=\"release-hint\">{{ skillBtnTitle }}</span>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- 同伴状态条（好感度/位置/状态） -->\r\n    <div v-else-if=\"store.selectedHero?.isCompanion\" class=\"companion-panel\">\r\n      <div class=\"companion-head\">\r\n        <span class=\"companion-title\">♥ 好感度</span>\r\n        <span class=\"companion-val\">{{ compBond }}<em>/100</em></span>\r\n        <span class=\"companion-tier\">{{ bondTierText }}</span>\r\n      </div>\r\n      <div class=\"companion-bar-bg\">\r\n        <div class=\"companion-bar-fill\" :style=\"{ width: Math.min(100, compBond) + '%' }\"></div>\r\n      </div>\r\n      <div class=\"companion-sub\">\r\n        <span class=\"csub-item\" v-if=\"compLoc\">📍 {{ compLoc }}</span>\r\n        <span class=\"csub-item\" v-if=\"compHpMax > 0\">❤️ {{ compHpNow }}/{{ compHpMax }}</span>\r\n        <span class=\"csub-item\" v-if=\"compBuffs.length\" title=\"异常状态\">⚠️ {{ compBuffs.join('、') }}</span>\r\n        <span class=\"csub-item\" v-if=\"compTier\">⚔ {{ compTier }}</span>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- 消息列表 -->\r\n    <div class=\"chat-messages\" ref=\"messagesRef\">\r\n      <div v-if=\"store.messages.length === 0\" class=\"chat-empty\">\r\n        <div class=\"empty-seal\">✧</div>\r\n        <p class=\"empty-text\">与{{ store.selectedHero?.displayName }}的对话即将开始…</p>\r\n        <p class=\"empty-hint\">在下方输入你的第一句话</p>\r\n      </div>\r\n      <div\r\n        v-for=\"(msg, idx) in store.messages\"\r\n        :key=\"idx\"\r\n        class=\"message-row\"\r\n        :class=\"msg.role === 'user' ? 'message-user' : 'message-assistant'\"\r\n        @mouseenter=\"hoveredIdx = idx\"\r\n        @mouseleave=\"hoveredIdx = -1\"\r\n      >\r\n        <div class=\"message-bubble\">\r\n          <div class=\"message-label\">{{ msg.role === 'user' ? '你' : store.selectedHero?.displayName }}</div>\r\n\r\n          <!-- 编辑模式 -->\r\n          <div v-if=\"editingIdx === idx\" class=\"message-edit-area\">\r\n            <textarea\r\n              v-model=\"editingText\"\r\n              class=\"message-edit-input\"\r\n              rows=\"3\"\r\n              ref=\"editTextareaRef\"\r\n              @keydown.enter.ctrl=\"onSaveEdit(idx)\"\r\n            ></textarea>\r\n            <div class=\"message-edit-actions\">\r\n              <button class=\"edit-action-btn edit-save\" @click=\"onSaveEdit(idx)\">✓ 保存</button>\r\n              <button class=\"edit-action-btn edit-cancel\" @click=\"onCancelEdit\">✗ 取消</button>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- 普通显示模式 -->\r\n          <div v-else class=\"message-content\">{{ msg.content }}</div>\r\n\r\n          <!-- 消息操作按钮（悬停显示） -->\r\n          <div v-if=\"hoveredIdx === idx && editingIdx !== idx\" class=\"message-actions\">\r\n            <button class=\"msg-action-btn\" @click=\"startEdit(idx, msg.content)\" title=\"编辑\">✏️</button>\r\n            <button class=\"msg-action-btn\" @click=\"onDelete(idx)\" title=\"删除\">🗑️</button>\r\n            <button v-if=\"msg.role === 'assistant'\" class=\"msg-action-btn\" @click=\"onRegenerate(idx)\" title=\"重新生成\">🔄</button>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      <div v-if=\"store.loading\" class=\"message-row message-assistant\">\r\n        <div class=\"message-bubble message-loading\">\r\n          <div class=\"message-label\">{{ store.selectedHero?.displayName }}</div>\r\n          <div class=\"loading-dots\">\r\n            <span class=\"dot\">·</span>\r\n            <span class=\"dot\">·</span>\r\n            <span class=\"dot\">·</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- 输入区 -->\r\n    <div class=\"chat-input-area\">\r\n      <textarea\r\n        v-model=\"inputText\"\r\n        class=\"chat-input\"\r\n        :placeholder=\"sleeping ? '她正沉睡……' : '输入你的话语…'\"\r\n        @keydown.enter.prevent=\"onSend\"\r\n        :disabled=\"store.loading || sleeping\"\r\n        rows=\"2\"\r\n      ></textarea>\r\n      <button class=\"send-btn\" @click=\"onSend\" :disabled=\"store.loading || !inputText.trim() || sleeping\">\r\n        {{ store.loading ? '…' : '✉' }}\r\n      </button>\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang=\"ts\">\r\nimport { computed, nextTick, onMounted, ref } from 'vue';\r\nimport { useHeroSpiritStore } from './store';\r\n\r\nconst store = useHeroSpiritStore();\r\nconst inputText = ref('');\r\nconst messagesRef = ref<HTMLElement | null>(null);\r\nconst hoveredIdx = ref(-1);\r\nconst editingIdx = ref(-1);\r\nconst editingText = ref('');\r\nconst editTextareaRef = ref<HTMLElement | null>(null);\r\nconst releaseMsg = ref('');\r\n\r\nconst onlineClass = 'is-online';\r\n\r\n// ---- 沉睡门控（方案D） ----\r\nconst sleeping = computed(() => (store.selectedHero ? store.isHeroSleeping(store.selectedHero) : false));\r\n\r\n// ---- 同伴状态（方案A：好感度/位置/HP/异常） ----\r\nconst compInfo = computed(() => store.selectedHero?.companionInfo || null);\r\nconst compBond = computed(() => Number(compInfo.value?.好感度 ?? 0));\r\nconst compLoc = computed(() => String(compInfo.value?.当前位置 || ''));\r\nconst compHpNow = computed(() => Number(compInfo.value?.hpNow ?? 0));\r\nconst compHpMax = computed(() => Number(compInfo.value?.hpMax ?? 0));\r\nconst compBuffs = computed(() => compInfo.value?.异常状态 || []);\r\nconst compTier = computed(() => String(compInfo.value?.等阶 || ''));\r\nconst bondTierText = computed(() => {\r\n  const b = compBond.value;\r\n  if (b >= 70) return '亲密';\r\n  if (b >= 30) return '友善';\r\n  return '疏远';\r\n});\r\n\r\n// ---- 英灵共鸣数据（stat_data.英灵） ----\r\nconst